import * as test from "bun:test"
import * as NFs from "node:fs"
import * as NKeys from "../src/internal/NKeys.ts"

const fixture = (name: string) =>
  NFs.readFileSync(new URL(`./fixtures/${name}`, import.meta.url), "utf8")

// generated by `nk -gen user -pubout` and `nk -sign`, see fixtures/README.md
const nkeyUser: { seed: string; publicKey: string; nonce: string; signature: string } = JSON.parse(
  fixture("nkey-user.json"),
)

const jwtClaims = (jwt: string) =>
  JSON.parse(Buffer.from(jwt.split(".")[1], "base64url").toString("utf8"))

test.describe("fromSeed", () => {
  test.it("derives the same public key as nk", () => {
    test.expect(NKeys.fromSeed(nkeyUser.seed).publicKey).toBe(nkeyUser.publicKey)
  })

  test.it("produces the same signature as nk", () => {
    const signature = NKeys.fromSeed(nkeyUser.seed).sign(new TextEncoder().encode(nkeyUser.nonce))

    test.expect(signature).toBe(nkeyUser.signature)
  })

  test.it("ignores surrounding whitespace", () => {
    test.expect(NKeys.fromSeed(`  ${nkeyUser.seed}\n`).publicKey).toBe(nkeyUser.publicKey)
  })

  test.it("rejects corrupted seeds without leaking them", () => {
    const flipped =
      nkeyUser.seed.slice(0, 10) + (nkeyUser.seed[10] === "A" ? "B" : "A") + nkeyUser.seed.slice(11)
    const cases: Array<[string, string]> = [
      [flipped, "checksum mismatch"],
      [nkeyUser.publicKey, "not a seed"],
      ["not-an-nkey!", "not base32"],
      ["SU", "too short"],
    ]
    for (const [input, message] of cases) {
      try {
        NKeys.fromSeed(input)
        throw new Error(`accepted ${message}`)
      } catch (error) {
        test.expect((error as Error).message).toContain(message)
        test.expect((error as Error).message).not.toContain(nkeyUser.seed)
      }
    }
  })
})

test.describe("parseCreds", () => {
  test.it("reads the JWT and seed of an nsc creds file", () => {
    const creds = NKeys.parseCreds(fixture("user.creds"))
    const claims = jwtClaims(creds.jwt)

    test.expect(claims.name).toBe("TestUser")
    test.expect(creds.seed.startsWith("SU")).toBe(true)
    // the JWT is issued to the public key of the seed in the same file
    test.expect(NKeys.fromSeed(creds.seed).publicKey).toBe(claims.sub)
  })

  test.it("accepts CRLF line endings", () => {
    const creds = NKeys.parseCreds(fixture("user.creds").replaceAll("\n", "\r\n"))

    test.expect(jwtClaims(creds.jwt).name).toBe("TestUser")
  })

  test.it("rejects contents without both blocks", () => {
    test
      .expect(() =>
        NKeys.parseCreds("-----BEGIN NATS USER JWT-----\neyJ\n------END NATS USER JWT------\n"),
      )
      .toThrow("expected a JWT and an NKey seed")
  })
})
